func (s *Server) GetStock(ctx context.Context, req *pb.GetStockRequest) (*pb.StockReply, error) {
	if req.Sku == "" {
		return nil, status.Error(codes.InvalidArgument, "sku is required")
	}

	stock, err := s.store.Lookup(context.Background(), req.Sku)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			return nil, fmt.Errorf("sku %q not found", req.Sku)
		}
		return nil, status.Errorf(codes.Internal,
			"lookup failed: dsn=%s err=%v", s.cfg.DatabaseURL, err)
	}

	return &pb.StockReply{Sku: req.Sku, Count: stock}, nil
}
